//! Import the data the neutral crafting system reads at match setup.

use std::collections::BTreeSet;
use std::fmt::Write;

use heatel::keyvalues::Kv;

use crate::install::Source;

pub fn table(source: &Source, script: &Kv) -> Result<String, String> {
    let root = child(script, "neutral_items")?;
    let limits = child(root, "madstone_limits")?;
    let unlimited = seconds(text(limits, "madstone_no_limit_time")?)?;
    let tiers = rows(root, "neutral_tiers")?;
    let mut out = format!(
        "//! Neutral crafting tiers, artifact pools and enchantment choices.\n\
         //! Generated by `tools/import_items`.\n\n\
         use crate::neutral_crafting::{{MadstoneAward, MadstoneBundle, NeutralArtifact, \
         NeutralArtifactPool, NeutralCrafting, NeutralEnchantment, NeutralEnchantments, NeutralTier}};\n\n\
         pub const NEUTRAL_CRAFTING: NeutralCrafting = NeutralCrafting {{\n\
         unlimited_after_seconds: {unlimited},\n",
    );
    emit_bundle(&mut out, source)?;
    out.push_str("tiers: &[\n");
    let mut last = None;
    for (index, (id, tier)) in tiers.iter().enumerate() {
        if id.parse::<usize>().ok() != Some(index + 1) {
            return Err(format!("invalid neutral tier order at {id}"));
        }
        let start = seconds(text(tier, "start_time")?)?;
        if last.map_or(start != 0, |previous| start <= previous) || start >= unlimited {
            return Err(format!("invalid neutral tier start at {id}"));
        }
        last = Some(start);
        emit_tier(&mut out, source, tier, start)?;
    }
    if last.is_none() {
        return Err("neutral tiers are empty".into());
    }
    out.push_str("],\n};\n");
    Ok(out)
}

fn emit_tier(out: &mut String, source: &Source, tier: &Kv, start: u32) -> Result<(), String> {
    let craft_cost = number::<u16>(tier, "craft_cost")?;
    let recraft_increment = tier
        .get("recraft_cost")
        .map(|_| number::<u16>(tier, "recraft_cost"))
        .transpose()?;
    let artifact_options = number::<u8>(tier, "trinket_options")?;
    let enchantment_options = number::<u8>(tier, "enhancement_options")?;
    let xp_bonus = number::<u32>(tier, "xp_bonus")?;
    writeln!(
        out,
        "NeutralTier {{ start_seconds: {start}, craft_cost: {craft_cost}, \
         recraft_increment: {recraft_increment:?}, xp_bonus: {xp_bonus}, \
         artifact_options: {artifact_options}, enchantment_options: {enchantment_options},"
    )
    .unwrap();
    out.push_str("artifact_pools: &[\n");
    let mut offered = 0u32;
    let mut artifacts = BTreeSet::new();
    for (key, pool) in rows(tier, "item_pools")? {
        offered += u32::from(emit_pool(out, source, key, pool, &mut artifacts)?);
    }
    if offered == 0 || offered > u32::from(artifact_options) {
        return Err("artifact draw count exceeds the available options".into());
    }
    out.push_str("],\n");
    emit_enchantments(out, source, tier, enchantment_options)?;
    out.push_str("},\n");
    Ok(())
}

fn emit_pool(
    out: &mut String,
    source: &Source,
    key: &str,
    pool: &Kv,
    artifacts: &mut BTreeSet<String>,
) -> Result<u8, String> {
    let draws = number::<u8>(pool, "options")?;
    let items = rows(pool, "items")?;
    if draws == 0 || usize::from(draws) > items.len() {
        return Err(format!("{key} draws {draws} from {} items", items.len()));
    }
    writeln!(out, "NeutralArtifactPool {{ draws: {draws}, artifacts: &[").unwrap();
    for (item, weight) in items {
        check_item(source, item, "ItemIsNeutralActiveDrop")?;
        let weight = scalar::<u32>(item, weight)?;
        if weight == 0 || !artifacts.insert(item.clone()) {
            return Err(format!("{item} is a repeated or zero-weight artifact"));
        }
        writeln!(
            out,
            "NeutralArtifact {{ key: {item:?}, weight: {weight} }},"
        )
        .unwrap();
    }
    out.push_str("] },\n");
    Ok(draws)
}

fn emit_enchantments(
    out: &mut String,
    source: &Source,
    tier: &Kv,
    options: u8,
) -> Result<(), String> {
    let enchantments = child(tier, "enhancements")?;
    let global = rows(enchantments, "global")?.len();
    out.push_str("enchantments: NeutralEnchantments {\n");
    for group in ["global", "strength", "agility", "intelligence", "universal"] {
        let choices = rows(enchantments, group)?;
        if group != "global" && choices.len() + global != usize::from(options) {
            return Err(format!("enchantment option count disagrees for {group}"));
        }
        writeln!(out, "{group}: &[").unwrap();
        let mut seen = BTreeSet::new();
        for (item, level) in choices {
            check_item(source, item, "ItemIsNeutralPassiveDrop")?;
            let level = scalar::<u8>(item, level)?;
            if level == 0 || !seen.insert(item) {
                return Err(format!("{item} is a repeated or zero-level enchantment"));
            }
            writeln!(
                out,
                "NeutralEnchantment {{ key: {item:?}, level: {level} }},"
            )
            .unwrap();
        }
        out.push_str("],\n");
    }
    out.push_str("},\n");
    Ok(())
}

fn emit_bundle(out: &mut String, source: &Source) -> Result<(), String> {
    let item = child(source.items(), "item_madstone_bundle")?;
    let values = child(item, "AbilityValues")?;
    let lifetime = number::<u32>(values, "die_time")?;
    writeln!(
        out,
        "bundle: MadstoneBundle {{ lifetime_seconds: {lifetime},"
    )
    .unwrap();
    for (mode, prefix) in [("normal", ""), ("turbo", "turbo_")] {
        let primary = award_vector(values, &format!("{prefix}madstone_primary"))?;
        let secondary = award_vector(values, &format!("{prefix}madstone_secondary"))?;
        if primary.len() != secondary.len() {
            return Err(format!("{mode} bundle award vectors disagree in length"));
        }
        writeln!(out, "{mode}: &[").unwrap();
        for (primary, secondary) in primary.into_iter().zip(secondary) {
            writeln!(
                out,
                "MadstoneAward {{ primary: {primary}, secondary: {secondary} }},"
            )
            .unwrap();
        }
        out.push_str("],\n");
    }
    out.push_str("},\n");
    Ok(())
}

fn award_vector(values: &Kv, name: &str) -> Result<Vec<u8>, String> {
    let vector: Vec<u8> = text(values, name)?
        .split_ascii_whitespace()
        .map(|word| {
            word.parse()
                .map_err(|_| format!("invalid {name} amount {word:?}"))
        })
        .collect::<Result<_, _>>()?;
    if vector.is_empty() {
        return Err(format!("{name} is empty"));
    }
    Ok(vector)
}

fn check_item(source: &Source, name: &str, flag: &str) -> Result<(), String> {
    let item = child(source.items(), name)?;
    if !name.starts_with("item_")
        || !name
            .bytes()
            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'_')
        || text(item, flag)? != "1"
        || text(item, "ItemPurchasable")? != "0"
    {
        return Err(format!("{name} is incompatible with the neutral item pool"));
    }
    Ok(())
}

fn child<'a>(parent: &'a Kv, name: &str) -> Result<&'a Kv, String> {
    parent
        .get(name)
        .ok_or_else(|| format!("neutral item data missing {name}"))
}

fn rows<'a>(value: &'a Kv, name: &str) -> Result<&'a [(String, Kv)], String> {
    child(value, name)?
        .block()
        .ok_or_else(|| format!("{name} must be a block"))
}

fn text<'a>(value: &'a Kv, name: &str) -> Result<&'a str, String> {
    match child(value, name)? {
        Kv::Text(text) => Ok(text),
        _ => Err(format!("{name} must be text")),
    }
}

fn number<T: std::str::FromStr>(value: &Kv, name: &str) -> Result<T, String> {
    scalar(name, child(value, name)?)
}

fn scalar<T: std::str::FromStr>(name: &str, value: &Kv) -> Result<T, String> {
    match value {
        Kv::Text(text) => text
            .parse()
            .map_err(|_| format!("invalid {name}: {text:?}")),
        _ => Err(format!("{name} must be numeric text")),
    }
}

fn seconds(clock: &str) -> Result<u32, String> {
    let invalid = || format!("invalid neutral clock {clock:?}");
    let (minutes, seconds) = clock.split_once(':').ok_or_else(invalid)?;
    let minutes: u32 = minutes.parse().map_err(|_| invalid())?;
    let seconds: u32 = seconds.parse().map_err(|_| invalid())?;
    if seconds >= 60 {
        return Err(invalid());
    }
    minutes
        .checked_mul(60)
        .and_then(|start| start.checked_add(seconds))
        .ok_or_else(invalid)
}
